            (N, self.out_channels, D_out, H_out, W_out),
            dtype=torch.float16,
            device='cuda'
        )

        total = N * self.out_channels * D_out * H_out * W_out
        block = 256
        grid_x = (total + block - 1) // block
        grid = (grid_x, 1, 1)

        args = [
            x.data_ptr(),
            self.weight.data_ptr(),
            out.data_ptr(),
            N,
            C_in,
            self.out_channels,
            D_in,
            H_in,
            W_in,
            D_out,
            H_out,
            W_out,
            K,
            s,
            p,
            d,
            total
        ]

