        returns: (N, C_out, D_out, H_out, W_out) fp16 CUDA tensor
        """
        assert x.is_cuda and x.dtype == torch.float16

        N, C_in, D_in, H_in, W_in = x.shape
        K = self.kernel_size
        s = self.stride
        p = self.padding
        d = self.dilation

        D_out = (D_in + 2 * p - d * (K - 1) - 1) // s + 1
        H_out = (H_in + 2 * p - d * (K - 1) - 1) // s + 1
        W_out = (W_in + 2 * p - d * (K - 1) - 1) // s + 1

        out = torch.empty(
            (N, self.out_channels, D_out, H_out, W_out),
            dtype=torch.float16,
            device='cuda'
        )

        total = N * self.out_channels * D_out * H_out * W_out
        block = 256
        grid_x = (total + block - 1) // block
        grid = (grid_x, 1, 1)

        args = [
            x.data_ptr(),
            self.weight.data_ptr(),
            out.data_ptr(),
            N,
            C_in,
            self.out_channels,
            D_in,
            H_in,
            W_in,
            D_out,
            H_out,
            W_out,
            K,
            s,
            p,
            d,
            total
        ]

        ptx_launch(self.module, "conv3d_fp16", grid, (block, 1, 1), args)

        return out
